{
  "findings": [
    {
      "check_id": "CKV_AZURE_44",
      "title": "Storage Account uses an insecure TLS version",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The storage account is configured with min_tls_version = \"TLS1_0\", which is deprecated and vulnerable to known attacks. It should be updated to TLS1_2 or higher."
    },
    {
      "check_id": "CKV_AZURE_39",
      "title": "Ensure Storage Account allows only secure transfer (HTTPS)",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "enable_https_traffic_only is set to false, allowing unencrypted HTTP traffic to the storage account, which exposes data in transit to interception."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version = \"TLS1_2\"\n  blob_properties {\n    versioning_enabled = true\n  }\n}",
  "fix_summary": "Updated min_tls_version from 'TLS1_0' to 'TLS1_2' to enforce modern encryption standards. Changed enable_https_traffic_only from false to true to ensure all traffic is encrypted via HTTPS."
}
